laya.xq.cfg.reportOneBug=function(errorMsg,errorObj){
	var scriptURI=Browser.window.location.href;
	var lineNumer=0;
	var columnNumber=0;
	if((typeof(reportBug)!='undefined')){
		reportBug(errorMsg ,scriptURI,lineNumer ,columnNumber,errorObj);
		}else{
		if(Browser.window.onerror){
			Browser.window.onerror(errorMsg ,scriptURI,lineNumer ,columnNumber,errorObj);
		}
	}
}
