var Main=(function(){
	function Main(){
		this.gameInit=null;
		this.versionUrl=null;
		this.font="FZYanSJW_Cu.TTF";
		this.loadVCount=0;
		this.curVer=null;
		
		this.reloadtimes=0;
		console.log("Main,test Version:"+Main.VER);
		this.gameInit=new GameInit();
		this.gameInit.onStart();
		SDKMgr.ins().update();
		if(Configs.enableDBCache){
			var handler=Handler.create(this,this.loadFileVersion);
			IndexDBMgr.instance().init(function(succes){
				handler.run();
			});
		}
		else{
			this.loadFileVersion();
		}
	}
	__class(Main,'Main');
	var __proto=Main.prototype;
	__proto.loadFileVersion=function(){
		this.loadVCount++;
		PreloadingView.loadingImg=Configs.startLoadUrl.preloadImgUrl;
		if(PathDefine.isPublish){
			NetMgr.AUTO_RECONNET=true;
			this.versionUrl='ver/'+fileVersion+'/version.json';
			console.log("版本字典路径："+this.versionUrl);
			Laya.loader.clearRes(this.versionUrl);
			Laya.loader.load([{url:this.versionUrl,type:"json"}] ,Handler.create(this ,this.onVersionDicLoaded));
		}
		else{
			Laya.loader.load([{url:PreloadingView.loadingImg,type:"image"},{url:Configs.startLoadUrl.uiUrl,type:"json"}],
			Handler.create(this,this.onLoaded));
		}
	}
	__proto.onVersionDicLoaded=function(){
		LogMgr.ins.report(3,{});
		var route=Laya.loader.getRes(this.versionUrl);
		if(!route){
			if(this.loadVCount >=6){
				WXSDK.isInWX && MiniAdpter.exitMiniProgram();
			}
			else
			this.loadFileVersion();
			return;
		}
		this.curVer=fileVersion;
		console.log("当前版本号：",this.curVer);
		if(WXSDK.isInWX){
			WXFileMgr.ins.init(this.curVer,route);
		}
		PathDefine.initVersion(route);
		if(AdaptConfig.ZlibEnabled){
			Laya.loader.load([{url:Configs.startLoadUrl.ui1Url,type:"arraybuffer"}] ,Handler.create(this ,this.onUiLoad));
			}else{
			Laya.loader.load([{url:Configs.startLoadUrl.uiPart1Url,type:"text"},
			{url:Configs.startLoadUrl.uiPart2Url,type:"text"},
			{url:Configs.startLoadUrl.uiPart3Url,type:"text"}] ,Handler.create(this ,this.onUiLoad));
		}
	}
	
	__proto.onWXZipLoad=function(code,data){
		Laya.loader.cacheRes("res/ui.json",JSON.parse(data.data));
		this.onUiLoad();
	}
	__proto.onUiLoad=function(){
		console.log("onUiLoad.");
		console.log("加载"+URL.formatURL(PreloadingView.loadingImg)+"文件")
		Laya.loader.load([
		{url:PreloadingView.loadingImg,type:"image"}],Handler.create(this,this.onLoaded));
	}
	__proto.onLoaded=function(){
		console.log("Main.onloaded：res/ui");
		var d=Loader.getRes(Configs.startLoadUrl.uiUrl);
		if(d){
			View.uiMap=d;
		}
		else{
			d=Loader.getRes(Configs.startLoadUrl.ui1Url);
			if(d){
				var b=new ByteArray(d);
				try{
					b.uncompress();
					var json=b.readUTFBytes(b.length);
					View.uiMap=JSON.parse(json);
					Loader.clearRes(Configs.startLoadUrl.ui1Url);
				}
				catch(error){
					this.clearRes();
				}
			}
			else{
				this.clearRes();
			}
		}
		console.log("Main.onloaded：res/ui/OK");
		if(WXSDK.isInWX){
			wx.hideLoading({});
			Laya.timer.loop(120000,MiniFileMgr$4,MiniFileMgr$4.updateFilesList);
		}
		this.gameInit.onEnd();
		if(Configs.FontLoadName){
			FontManager.addFont("@"+Configs.FontLoadName,"SimHei",Handler.create(this,this.onFontloaded));
			}else{
			FontManager.addFont(PathDefine.FONT+this.font,"SimHei",Handler.create(this,this.onFontloaded));
		}
		BaseSDK.ins.setLoadingProgress(90);
	}
	__proto.clearRes=function(){
		var json1="";
		for(var i=1;i<=3;i++){
			var d=Loader.getRes(Configs.startLoadUrl["uiPart"+i+"Url"]);
			if(d==null){
				if(this.reloadtimes > 2){
					if(Browser.onWeiXin){
						MiniAdpter.exitMiniProgram();
					}
				}
				this.reloadtimes++;
				this.onVersionDicLoaded();
				return;
			}
			json1+=d;
			Loader.clearRes(Configs.startLoadUrl["uiPart"+i+"Url"]);
		}
		View.uiMap=JSON.parse(json1);
	}
	__proto.onFontloaded=function(){
		var removeFunc=Browser.window.removeLoading;
		removeFunc&&removeFunc();
		var healthV=new HealthTips();
		Laya.stage.addChildAt(healthV,0);
	}
	Main.VER="21.07.28.2";
	return Main;
})()
var CommonItemGunDong=(function(){
	function CommonItemGunDong(){
		this._aryItem=null;
		this.isDirection=false;
	}
	__class(CommonItemGunDong,'view.modules.common.CommonItemGunDong');
	var __proto=CommonItemGunDong.prototype;
	__proto.yiDong=function(){
		var len=this.aryItem.length;
		if(this.isDirection){
			for (var i=len-1;i >=0;i--){
				var item=this.aryItem[i];
				item.y=item.y+3;
				if(item.y >=len*item.height){
					item.y=-item.height+30;
					this.aryItem.push(item);
					this.aryItem.splice(i,1);
				}
			}
			}else{
			for (var j=0;j < len;j++){
				var item_=this.aryItem[j];
				item_.y=item_.y-3;
				if(item_.y <=-item_.height){
					item_.y=this.aryItem[len-1].y+item_.height+5;
					this.aryItem.push(item_);
					this.aryItem.splice(j,1);
				}
			}
		}
	}
	
	__proto.start=function(){
		Laya.timer.loop(50,this,this.yiDong);
	}
	
	__proto.suspend=function(){
		Laya.timer.clear(this,this.yiDong);
		this.removeArray();
	}
	__proto.removeArray=function(){
		if(this.aryItem){
			var len=this.aryItem.length;
			for (var i=0;i < len;i++){
				this.aryItem[i].removeSelf();
			}
			this.aryItem.length=0;
		}
	}
	__getset(0,__proto,'aryItem',function(){
		return this._aryItem;
		},function(value){
		this._aryItem=value;
	});
	return CommonItemGunDong;
})()
