__proto.getBagItemMsgs=function(itemMsgs){
	this.red.hideRedPoint("bag","clear",RedTypeEnum.Bag);
	this.bagGemArr=[];
	this.bagEquipArr=[];
	this.bagItemArr=[];
	this.bagFaBaoArr=[];
	this.bagTuJianArr=[];
	var gemArr=[];
	var faBaoArr=[];
	var tuJianArr=[];
	var itemArr=[];
	var equipArr=[];
	this.bagGoodsArr.length=0;
	this.bagGoodsArr.length=this.bagCapacity;
	this.equipPartDic={};
	this.bagGuidDic={};
	this.bagGoodLen=itemMsgs.length;
	for (var i=0;i < this.bagGoodLen;i++){
		var itemMsg=itemMsgs[i];
		var templateId=itemMsg.templateId;
		var firstStr=templateId.substr(0,1);
		switch(firstStr){
			case "d":{
					var d=this.createItemVo(itemMsg);
					if(!d)break ;
					d.whichPanel=0;
					if(d.cfgItem.category==2){
						gemArr.push(d);
					}
					else if(d.cfgItem.category==33){
						faBaoArr.push(d);
					}
					else if(d.cfgItem.category==35){
						tuJianArr.push(d);
					}
					else{
						itemArr.push(d);
					}
					this.bagGoodsArr[itemMsg.slotNum-1]=d;
					this.bagGuidDic[itemMsg.guid]=d;
					if(d.cfgItem.skill=="10"||d.cfgItem.category==200){
						this.red.showRedPoint("bag","clear",RedTypeEnum.Bag);
					}
					break ;
				}
			default :{
					var z=this.createEquipVO(itemMsg);
					if (z==null){
						return;
					}
					z.whichPanel=0;
					this.pushEquipPartDic(z);
					this.bagGoodsArr[itemMsg.slotNum-1]=z;
					this.bagGuidDic[itemMsg.guid]=z;
					equipArr.push(z);
					break ;
				}
			}
	}
	this.itemChanged();
	this.updateBagByType(itemArr,1);
	this.updateBagByType(gemArr,2);
	this.updateBagByType(faBaoArr,3);
	this.updateBagByType(tuJianArr,5);
	this.updateBagByType(equipArr,4);
	this.bagEquipArr=this.bagEquipArr.sort(this.compare);
	this.checkBestScoreEquip();
	EventCenter.instance.event("ITEM_LIST_UPDATED");
	this.equipLen=equipArr.length;
	this.itemLen=itemArr.length;
	this.gemLen=gemArr.length;
	this.fabaoLen=faBaoArr.length;
	this.tuJianLen=tuJianArr.length;
	if((this.equipLen+6)>=this.getMaxCountByBagType(4)){
		this.bagIsFull=true;
		EventCenter.instance.event("bag_all_fill",[true]);
		if(Mgr.chaoZhiTeDianMgr.isBuyZz || Mgr.gqMgr.openAutoCha){
			Laya.timer.callLater(this,this.autoSmeltEquip);
		}
	}
	else{
		this.bagIsFull=false;
		EventCenter.instance.event("bag_all_fill",[false]);
	}
}
