__proto.getEquipBySlot=function(slot,lv){
	if(!this.equipPartDic)
		return null;
	var ary=this.equipPartDic[slot];
	var maxScoreValue=0;
	var index=-1;
	if(ary && ary.length > 0){
		for (var i=0;i < ary.length;i++){
			var obj=ary [i];
			if(obj && obj.cfgItem.itemlevel <=lv){
				if (obj.totalScore > maxScoreValue){
					maxScoreValue=obj.totalScore;
					index=i;
				}
			}
		}
	}
	else
	return null;
	return ary [index];
}
