__proto.getEquipVoByTwo=function(starLv,rarelv,state,equipType){
	(state===void 0)&& (state=0);
	(equipType===void 0)&& (equipType=1);
	var equipArr=[];
	var len=this.bagEquipArr.length;
	for (var i=0;i < len;i++){
		var vo=this.bagEquipArr[i];
		if(vo){
			switch(state){
				case 0:
					if((vo.cfgItem.eqpart==7 || vo.cfgItem.eqpart==8))
						continue ;
				case 1:
					if(starLv !=parseInt(vo.cfgItem.star)|| rarelv !=vo.cfgItem.rarelevel){
						continue ;
					}
					break ;
				case 2:
					if((vo.cfgItem.eqpart !=7 && vo.cfgItem.eqpart !=8))
						continue ;
					break ;
				case 3:
					if(vo.cfgItem.eqpart !=7)
						continue ;
					break ;
				case 4:
					if(vo.cfgItem.eqpart !=8)
						continue ;
					break ;
				}
			if(vo.type==equipType)
				equipArr.push(vo);
		}
	}
	return equipArr
}
