__proto.checkItemIsEnough=function(items,checkBind){
	(checkBind===void 0)&& (checkBind=-1);
	if(!items)return true;
	if((items instanceof Array)){
		var arr=items;
	}
	else if((typeof items=='string')){
		arr=items.split(";");
	};
	var len=arr.length;
	for(var i=0;i< len;i++){
		if(!arr[i] || arr[i]==""){
			continue ;
		};
		var itemArr=arr[i].split(":");
		var itemId=itemArr[0];
		var num=parseInt(itemArr[1]);
		var config=this.iCfg.getItemByField("id",itemId);
		if(!config){
			config=this.eCfg.getItemByField("id",itemId);
			if(!config){
				console.error("道具不存在！！！"+itemId);
				return false;
			}
		}
		if(config.category==18){
			if(!this.minggeMgr.checkMinggeIsEnough(itemId,num)){
				return false;
			}
			}else{
			var totalNum=this.getBagMatCount(itemId,checkBind);
			if(num>totalNum){
				return false;
			}
		}
	}
	return true;
}
