			var stage=Laya.stage;
			var vo=collect.vo;
			vo.state=1;
			this.coolectEF=CoolingMaskUtil.createCollectEff("采集中",this.collectVO.cooldown+500,(stage.width>>1),stage.height>>1,stage,Handler.create(this,this.checkIsCollect));
