	__proto.getOpenState=function(type,value){
		var vis=false
		if(type==1){
			var lv=NetMgr.ins().roleVO.level;
			if(lv >=value)
				vis=true
		}
		else if(type==2){
			var bo=Mgr.task.curTask.state==2
			if((Mgr.task.curTask.id2==value && bo)){
				vis=true;
				}else if(Mgr.guide.taskModel.compareTaskId(Mgr.task.curTask.id2,value)){
				vis=true;
			}
		}
		else if(type==4){
			lv=CommonUtil.openServerDay;
			if(lv >=value)
				vis=true
		}
		else if(type==5){
			if(Mgr.gqMgr.gqInfo){
				lv=Mgr.gqMgr.gqInfo.nextLevel-1;
			}
			else{
				lv=100;
			}
			if(lv >=value)
				vis=true
		}
		else if(type==6){
			lv=NetMgr.ins().roleVO.vipLevel;
			if(lv >=value)
				vis=true
		}
		return vis
	}
	__proto.getTipStr=function(limit,value){
		if(limit==2){
			var tempVo=Mgr.task.getTaskVoById(value);
			if(tempVo){
				return "完成任务【"+tempVo.name2+"】后";
			}
		}
		else if(limit==4){
			return "开服"+value+"天后"
		}
		else if(limit==5){
			return "关卡达到"+value+"关后";
		}
		else if(limit==6){
			return "Svip达到"+value+"级后"
		}
		return ""
	}
