	__proto.getPassInfoByType=function(type,isGuid){
		(isGuid===void 0)&& (isGuid=false);
		var ytg=1000;
		var wkq=500;
		var ksd=200;
		var arr=Mgr.copy.coungMsgs || [];
		var newArr=[];
		var len=arr.length;
		for (var i=0;i <len;i++){
			var msg=arr[i];
			var obj=this.materialCopyCfgData.getItemByField("mainid",msg.id);
			if(!obj){
				obj["sortFlag"]=ytg++;
				continue ;
			}
			obj["sortFlag"]=msg.id;
			var openBo=false;
			var tempAry=this.checkOpen(obj.limit,obj.value);
			openBo=tempAry[0];
			if(openBo && obj.value1){
				tempAry=this.checkOpen(obj.limit1,obj.value1);
				openBo=tempAry[0];
			};
			var info=this.getCtOb(obj.mainid);
			var c=info.ynCount;
			var vipc=info.vipCount;
			var svipc=info.svipCount;
			if(!openBo){
				obj["sortFlag"]=wkq++;
			};
			var ybsdMsg=this.getSyCt(obj.mainid);
			var sdCOunt=ybsdMsg.ynCount+ybsdMsg.svipCount+ybsdMsg.vipCount;
			if(msg.count <=0){
				if(sdCOunt > 0){
					obj["isPass"]=sdCOunt;
					}else{
					obj["isPass"]=1000;
				}
				if(vipc==0 && svipc==0){
					obj["sortFlag"]=ytg++;
					}else{
					obj["sortFlag"]=ksd++;
				}
			}
			else{
				obj["isPass"]=999;
			}
			newArr.push(obj);
		};
		var sortFun=function (o,p){
			return o.mainid-p.mainid;
		};
		var sortFun2=function (o,p){
			return o["sortFlag"]-p["sortFlag"];
		}
		if(!isGuid){
			newArr=newArr.sort(sortFun2);
		}
		else{
			newArr=newArr.sort(sortFun);
		}
		return newArr;
	}
