	__proto.findBetterEquip=function(){
		if(this.curModel==null){
			return;
		};
		var bagArr=Mgr.bag.bagGoodsArr;
		var bagLen=Mgr.bag.bagGoodLen;
		if (bagLen > 0){
			var pydata=Mgr.payLine.model.curModel;
			for (var i=1;i <=10;i++){
				var roleVO=NetMgr.ins().roleVO;
				var maxScoreValue=0;
				if(this.curModel.wearEquipDic[i])
					maxScoreValue=this.curModel.wearEquipDic[i].totalScore;
				else
				maxScoreValue=0;
				for (var j=0;j < bagLen;j++){
					var b=bagArr[j];
					if (bagArr[j] !=null && b.partPos==i && b.cfgItem.levelreq <=this.role.zhuanshengLevel && b.cfgItem.levelwears <=this.role.level){
						if(Mgr.yuanShenM.checkIfYuanShenEquip(b)||Mgr.zhuoYueZhuangBeiM.checkIfZhuoYueEquip(b)){
							continue ;
						}
						if(parseInt(b.cfgItem.type)> 1){
							var serInfo=pydata.myPayLineInfo[parseInt(b.cfgItem.type)];
							if(serInfo){
								var jieshu=serInfo? serInfo.jieshu :1;
								if(parseInt(b.cfgItem.itemlevel)> jieshu)
									return;
							}
							else
							return;
						}
						if (b.cfgItem.job==this.role.job || b.cfgItem.job=="0"){
							if (b.totalScore > maxScoreValue){
								EventCenter.instance.event("UPGRAD_OPTION_TIP",[4,false]);
								this.curModel.wearDic[i]=b;
								maxScoreValue=b.totalScore;
							}
						}
					}
				}
			}
		}
	}
	
