	__proto.changeQuality=function(e){
		var guid=e.itemGuid;
		var itemMsg=e.item;
		var newE=this.createEquipVO(itemMsg);
		for (var i=0;i < this.wearEquips.length;i++){
			var wearE=this.wearEquips[i];
			if (wearE.guid==guid){
				this.wearEquips[i]=newE;
				break ;
			}
		}
		Mgr.equipPro.sendGetRoleEquipMsg(Mgr.subPlayer.curGuid);
		Mgr.equipPro.sendEquipStrengthInfo(Mgr.subPlayer.curGuid);
		this.checkUpQualityTab();
		EventCenter.instance.event("EQUIP_UP_QUALITY",newE);
	}
	
