	__proto.checkEquipCanReplaceRole=function(equipVO){
		var levelReq=equipVO.cfgItem.levelreq;
		var zhuanshengLevel=NetMgr.ins().roleVO.zhuanshengLevel;
		var wearLevel=equipVO.cfgItem.levelwears;
		var level=NetMgr.ins().roleVO.level;
		if (levelReq <=zhuanshengLevel && level >=wearLevel){
			var subVo=Mgr.subPlayer.getSubPlayerVo(NetMgr.ins().roleVO.guid);
			if(subVo==null)return 0;
			var equipModel=Mgr.equip.getModelbyRoleId(subVo.roleId);
			var wearedEquip=equipModel.wearEquipDic[(equipVO.partPos)];
			if(!wearedEquip){
				equipVO.replaceRoleId=subVo.roleId;
				return subVo.roleId;
			};
			var changeEquipVo=wearedEquip.changeVO;
			if(changeEquipVo && changeEquipVo.replaceRoleId==0){
				changeEquipVo=null;
			}
			if(changeEquipVo){
				if(changeEquipVo==equipVO){
					equipVO.replaceRoleId=subVo.roleId;
					return subVo.roleId;
				}
				if(changeEquipVo.totalScore < equipVO.totalScore){
					wearedEquip.changeVO=equipVO;
					equipVO.replaceRoleId=subVo.roleId;
					this.checkEquipCanReplaceRole(changeEquipVo);
					return subVo.roleId;
				}
			}
			else if (wearedEquip && (wearedEquip.totalScore < equipVO.totalScore)&& equipVO.cfgItem.levelwears <=NetMgr.ins().roleVO.level){
				wearedEquip.changeVO=equipVO;
				equipVO.replaceRoleId=subVo.roleId;
				return subVo.roleId;
			}
		}
		equipVO.replaceRoleId=0;
		return 0;
	}
	
	__proto.checkEquipBestScore=function(equipVO){
		var subVo=Mgr.subPlayer.getSubPlayerVo(NetMgr.ins().roleVO.guid);
		if(!subVo){
			return false;
		};
		var equipModel=Mgr.equip.getModelbyRoleId(subVo.roleId);
		var wearedEquip=equipModel.wearEquipDic[(equipVO.partPos)];
		var levelReq=equipVO.cfgItem.levelreq;
		var zhuanshengLevel=NetMgr.ins().roleVO.zhuanshengLevel;
		var wearLevel=equipVO.cfgItem.levelwears;
		var level=NetMgr.ins().roleVO.level;
		if (levelReq <=zhuanshengLevel && level >=wearLevel){
			if(!wearedEquip)return true;
			if(equipVO.attrScore > wearedEquip.attrScore){
				return true;
				}else{
				return false;
			}
		}
		return false;
	}
	__proto.getEquipSpecialAttr=function(o){
		var specialAttrArr=[];
		var specialArr;
		if(o.makeAttributes){
			specialArr=o.makeAttributes;
		}
		else{
			specialArr=o.itemMsg.makeAttributes;
		};
		var len=specialArr.length;
		for (var i=0;i < len;i++){
			var special_1=Mgr.equipCompMgr.getSpecialAttrById(specialArr[i]);
			var obj=AttributeTypeEnum.getAttrObj(special_1.type);
			var attr1=new AttributeMsg();
			attr1.attrId=parseInt(obj.id);
			attr1.attrValue=parseFloat(special_1.value);
			specialAttrArr.push(attr1);
		}
		return specialAttrArr;
	}
	
	__proto.equipSort=function(equipSortArr){
		var arr=[];
		var len=equipSortArr.length;
		var part7;
		var part8;
		for (var i=0;i < len;i++){
			var obj=equipSortArr[i];
			var part=obj.partPos || obj.pos;
			if(part==7){
				part7=obj;
				}else if(part==8){
				part8=obj;
				}else{
				arr.push(obj);
			}
		}
		arr.push(part7);
		arr.push(part8);
		return arr;
	}
	
