	__proto.compoundGem=function(g){
		var part=g.part;
		var slot=g.slot;
		var resultGemId=g.resultBaoshiId;
		var resultGem=Mgr.item.getItemVO(resultGemId);
		var arr=Mgr.equip.curModel.gemPartSlotDic[part];
		var curGemArr=Mgr.equip.curModel.wearEquipDic[part].gemArr;
		for (var i=0;i < arr.length;i++){
			var partGemVO1=arr [i];
			if(parseInt(partGemVO1.slot)==g.slot){
				partGemVO1.templateId=g.resultBaoshiId;
			}
			if(curGemArr[i].slot==g.slot){
				curGemArr[i].templateId=g.resultBaoshiId;
			}
			partGemVO1.state=this.checkGemState(partGemVO1,Mgr.equip.curModel);
		}
		Mgr.itemPro.sendGetBagGoodsMsg();
		var equipModel=Mgr.equip.getModelbyRoleId(g.roleId);
		var equipArr=equipModel.wearEquipArr;
		var len=equipArr.length;
		for (var j=0;j < len;j++){
			if(equipArr[j].partPos==part){
				var equipVo=equipArr[j];
				equipVo.gemArr[slot-1].templateId=resultGemId;
			}
		}
		equipModel.wearEquipDic[part].gemArr[slot-1].templateId=resultGemId;
		this.refreshGemRed(equipModel);
		Laya.timer.frameOnce(5,this,this.delayEquipGem,[arr,slot,equipModel]);
	}
