	__proto.checkGongMingRed=function(msg){
		if(msg.nextLevel==msg.level){
			this.red.hideRedPoint("dzbaoshi",msg.roleId+"_gem"+msg.type,RedTypeEnum.GemRed);
			return;
		}
		else{
			var gongMingInfo=Mgr.equip.getGongMingByTwoJieShu(msg.type,msg.level);
			var nextGongMingInfo=Mgr.equip.getGongMingByTwoJieShu(msg.type,msg.nextLevel);
			if(nextGongMingInfo){
				if(!msg.isActive && msg.totalLevel >=parseInt(gongMingInfo.level)){
					this.red.showRedPoint("dzbaoshi",msg.roleId+"_gem"+msg.type,RedTypeEnum.GemRed);
				}
				else if(msg.totalLevel >=parseInt(nextGongMingInfo.level)){
					this.red.showRedPoint("dzbaoshi",msg.roleId+"_gem"+msg.type,RedTypeEnum.GemRed);
				}
				else{
					this.red.hideRedPoint("dzbaoshi",msg.roleId+"_gem"+msg.type,RedTypeEnum.GemRed);
				}
			}
		}
	}
	
	__proto.checkHaveChangeGem=function(vo){
		if (vo==null || vo.templateId==""){
			return 0;
		};
		var bagGemArr=this.getBagGemArr(vo.gemType);
		var gemFV=Mgr.item.getGemFV([vo.templateId]);
		for (var i=0;i < bagGemArr.length;i++){
			var bagGemVO=bagGemArr[i];
			var bagGemFV=Mgr.item.getGemFV([bagGemVO.templateId]);
			if (bagGemFV > gemFV){
				return 2;
			}
		}
		return 0;
	}
	
	__proto.checkHaveCompoundGem=function(vo){
		if (vo==null || vo.templateId==""){
			return 0;
		};
		var bagCount=Mgr.bag.getBagMatCount(vo.templateId);
		var gemCfgMsg=this._model.getGemCofById(vo.templateId);
		if (gemCfgMsg==null){
			return 0;
		};
		var needCount=parseInt(gemCfgMsg.num);
		if (bagCount >=needCount){
			return 3;
		}
		else{
			return 0;
		}
	}
	__proto.getCanMergeCount=function(vo,lowLv){
		var count=0;
		if(lowLv==0){
			return count;
		};
		var arr=this._model.getGemsByType(parseInt(vo.gemType));
		var len=arr.length;
		var tempArr=[];
		for (var j=0;j < len;j++){
			tempArr[j]=0;
		}
		for (var i=0;i < len;i++){
			var ele=arr[i];
			var lowObj=ele.getCfgData();
			var bagCount=Mgr.bag.getBagMatCount(lowObj.id)+tempArr[i];
			var meregeCount=Math.ceil(bagCount / lowObj.num);
			tempArr[i+1]=meregeCount;
			if(lowObj.level==lowLv){
				return meregeCount;
			}
		}
		return count;
	}
	
