		var arr=godEquipInfo.equips;
		this.godEquipArr=[];
		equipModel.ownGodEquipDic[godEquipInfo.type]={};
		for (var i=0;i < arr.length;i++){
			var msg=arr[i];
			equipModel.ownGodEquipDic[godEquipInfo.type][msg.part]=msg;
		}
		for (var j=0;j < this.partArr.length;j++){
			var vo;
			var part=this.partArr[j];
			if (equipModel.ownGodEquipDic[godEquipInfo.type][part]){
				var msg1=equipModel.ownGodEquipDic[godEquipInfo.type][part];
				vo=this.createVO(part,msg1.level,godEquipInfo.type);
			}
			else
			vo=this.createVO(part,1,godEquipInfo.type);
			this.getGodEquipState(vo,godEquipInfo.roleId);
			this.godEquipArr[j]=vo;
		}
		equipModel.godEquipDic[godEquipInfo.type]=this.godEquipArr;
		this.checkShenZhuangRed(equipModel.godEquipDic[godEquipInfo.type],godEquipInfo.roleId);
