	__proto.getGodEquipState=function(vo,roleId){
		var equipModel=Mgr.equip.getModelbyRoleId(roleId);
		if(equipModel.ownGodEquipDic[vo.type][vo.part]){
			var next=vo.nextName;
			if (next !="")
				vo.isCompNext=Mgr.item.checkMatIsEnou(vo.upId,vo.upCount);
			if(vo.nextAttrArr && vo.isCompNext)
				vo.state=5;
			else if(vo.nextAttrArr)
			vo.state=2;
			else
			vo.state=3;
		}
		else{
			if (Mgr.bag.getBagMatCount(vo.needItem)> 0)
				vo.state=1;
			else
			vo.state=0;
		}
	}
	__proto.refreshChuanShi=function(type,roleId){
		var equipModel=Mgr.equip.getModelbyRoleId(roleId)
		var equipArr=[];
		for (var j=0;j < this.partArr.length;j++){
			var vo;
			var part=this.partArr[j];
			if(!equipModel.ownGodEquipDic[type])continue ;
			if (equipModel.ownGodEquipDic[type][part]){
				var msg1=equipModel.ownGodEquipDic[type][part];
				if(msg1.lv)
					vo=this.createVO(part,msg1.lv,type);
				else
				vo=this.createVO(part,msg1.level,type);
			}
			else
			vo=this.createVO(part,1,type);
			this.getGodEquipState(vo,roleId);
			equipArr[j]=vo;
		}
		equipModel.godEquipDic[type]=equipArr;
		this.checkShenZhuangRed(equipModel.godEquipDic[type],roleId);
	}
	
