				this.red.showRedPoint("chuanshizhuangbei",roleId+"_"+shenZhuangVo.type+RedTypeEnum.GodEquip ,RedTypeEnum.GodEquip);
				this.red.showRedPoint("chuanshizhuangbei",roleId+"_"+shenZhuangVo.type+shenZhuangVo.part+RedTypeEnum.GodEquip ,RedTypeEnum.GodEquip);
