	__proto.createVO=function(part,lv,equipType){
		var vo=new ChuanshiVO();
		vo.type=equipType;
		var obj=this.getObj(equipType,part,lv);
		var nextObj=this.getObj(equipType,part,lv+1);
		vo.cfgItem=obj;
		vo.part=parseInt(obj.type);
		vo.speUrl=PathDefine.IMAGE+"chuanshi/special"+obj.special+".png";
		vo.partName=Mgr.equip.getPartName(vo.part);
		vo.lv=parseInt(obj.level);
		vo.nameStr=obj.name;
		var str2=obj.icon;
		var arr2=str2.split(";");
		if (arr2.length > 1){
			if (this.job=="A"){
				vo.icon=PathDefine.getIconUrl(arr2[0]);
			}
			else{
				vo.icon=PathDefine.getIconUrl(arr2[1]);
			}
		}
		else{
			vo.icon=PathDefine.getIconUrl(obj.icon);
		};
		var str3=obj.mod;
		var arr3=str3.split(";");
		if (arr3.length > 1){
			if (this.job=="A"){
				vo.mod=PathDefine.EFFECT_UI+"chuanshi/"+arr3[0]+".amt";
			}
			else{
				vo.mod=PathDefine.EFFECT_UI+"chuanshi/"+arr3[1]+".amt";
			}
		}
		else{
			vo.mod=PathDefine.EFFECT_UI+"chuanshi/"+obj.mod+".amt";
		}
		vo.rightTop=vo.lv;
		vo.needItem=obj.needItem;
		var compStr=obj.hecheng;
		if (compStr !=""){
			var compArr=compStr.split(":");
			vo.compId=compArr[0];
			vo.compCount=parseInt(compArr[1]);
			vo.canComp=true;
			vo.isCompNext=Mgr.item.checkMatIsEnou(compStr);
		}
		else{
			vo.canComp=false;
			vo.isCompNext=false;
		};
		var str1=obj.fenjie;
		if (str1 !=""){
			var arr1=str1.split(":");
			vo.recId=arr1[0];
			vo.recCount=parseInt(arr1[1]);
		}
		vo.attrArr=AttributeTypeEnum.getAttrArrByCfgMsg(obj);
		vo.fv=AttributeTypeEnum.getAttrArrTotalFVByCfgMsg(obj);
		var spe=obj.special;
		var speArr=spe.split(":");
		vo.speVal=parseFloat(speArr[2]);
		if (nextObj){
			vo.nextUpValArr=[];
			vo.nextAttrArr=AttributeTypeEnum.getAttrArrByCfgMsg(nextObj);
			vo.nextName=nextObj.name;
			vo.nextFV=AttributeTypeEnum.getAttrArrTotalFVByCfgMsg(nextObj);
			for (var i=0;i < vo.attrArr.length;i++){
				var nowAttrVO=vo.attrArr[i];
				var nextAttrVO=vo.nextAttrArr[i];
				vo.nextUpValArr.push(parseInt(nextAttrVO.attrValue)-parseInt(nowAttrVO.attrValue));
			};
			var str=nextObj.hecheng;
			if (str !=""){
				var arr=str.split(":");
				vo.upId=arr[0];
				vo.upCount=parseInt(arr[1]);
			};
			var nextSpe=nextObj.special;
			var nextSpeArr=nextSpe.split(":");
			var nextVal=parseFloat(nextSpeArr[2]);
			vo.nextUpSpeVal=(nextSpeArr[2] *100-vo.speVal *100)/100;
		}
		if (obj.skill !=""){
			var skillVO=SkillManager.ins.getData(obj.skill,false,vo.lv);
			vo.skillVO=skillVO;
		}
		return vo;
	}
	
	__proto.createRexueVO=function(part,e){
		var roleLv=NetMgr.ins().roleVO.level;
		var vo=new ChuanshiVO();
		vo.part=part;
		var arr=Mgr.equip.getEArrByPartRare(part,6);
		if (e){
			if (e.rareLv==6){
				vo.e=e;
			}
			for (var i=0;i < arr.length;i++){
				var temp=arr[i];
				if (temp.totalScore > e.totalScore){
					vo.nextE=temp;
					if (vo.e){
						vo.nextUpValArr=[];
						for (var j=0;j < vo.e.attrArr.length;j++){
							var nowAttrVO=vo.e.attrArr[j];
							var nextAttrVO=vo.nextE.attrArr[j];
							var changeVal=parseInt(nextAttrVO.attrValue)-parseInt(nowAttrVO.attrValue);
							vo.nextUpValArr.push(changeVal);
						}
					}
					break ;
				}
			}
		}
		else{
			vo.nextE=arr[0];
		}
		if (vo.nextE){
		}
		return vo;
	}
	
