	__proto.checkGongMingRed=function(msg){
		var isQiangHua=msg.type !=24;
		var resonanceType=isQiangHua?"dzqianhua":"dzshengxing";
		var eventType=isQiangHua?RedTypeEnum.ForgeEnhance:RedTypeEnum.ForgeUpStar;
		if(msg.nextLevel==msg.level){
			this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
			return;
		}
		else{
			if(msg.type==24){
				var gongMingInfo=Mgr.equip.getGongMingByTwo(msg.type,msg.level);
				var nextGongMingInfo=Mgr.equip.getGongMingByTwo(msg.type,msg.nextLevel);
				if(nextGongMingInfo){
					if(!msg.isActive && msg.totalLevel >=parseInt(gongMingInfo.level)){
						this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
					}
					else if(msg.totalLevel >=parseInt(nextGongMingInfo.level)){
						this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
					}
					else{
						this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
					}
				}
				}else{
				gongMingInfo=Mgr.equip.getGongMingByTwoJieShu(msg.type,msg.level);
				nextGongMingInfo=Mgr.equip.getGongMingByTwoJieShu(msg.type,msg.nextLevel);
				if(nextGongMingInfo){
					if(msg.type==20){
						if(!msg.isActive && (this.getReachNum(parseInt(gongMingInfo.level),false)>=8)){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else if(this.getReachNum(parseInt(nextGongMingInfo.level),false)>=8){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else{
							this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						}else{
						if(!msg.isActive && (this.getReachNum(parseInt(gongMingInfo.level),true)>=10)){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else if(this.getReachNum(parseInt(nextGongMingInfo.level),true)>=10){
							this.red.showRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
						else{
							this.red.hideRedPoint(resonanceType,msg.roleId+"_"+msg.type,eventType);
						}
					}
				}
			}
		}
	}
	
