		if(type==1 || this.checkSpType(type))return false;
		var zwtFloor=Mgr.copy.zxzCurId;
		var unLock=cfg.unlockLevel?cfg.unlockLevel:0;
		if(zwtFloor<unLock)return false;
		var dressInfo=this._model.getDressInfoByType(type);
		if(!dressInfo)return !this.checkDressFull();
		var dressCfg=this.getMGCof(dressInfo.templateId);
		if(cfg.quality>dressCfg.quality)return true;
