	__proto.refreshXQ=function(){
		if(!Mgr.guide.isOpen("zhanWen"))return;
		var bo=false;
		var gridLen=this._model.PAGE_SIZE;
		var spType=0;
		var dressInfo;
		var maxLv=this._model.getMaxLv();
		for(var i=1;i<=gridLen;i++){
			spType=this.getSpecialType(i);
			if(spType){
				dressInfo=this.getDressInfoByGrid(i);
				if(!dressInfo){
					var key="xq"+spType;
					this.red.hideRedPoint("zhanWen",key,RedTypeEnum.RoleOneMenuRed);
					if(this.checkHasSpe(spType)){
						this.red.showRedPoint("zhanWen",key,RedTypeEnum.RoleOneMenuRed);
						bo=true;
					}
				}
				else{
					var cfg=this.getMGCof(dressInfo.templateId);
					var lv=dressInfo.level;
					var curLvCfg=this.getMgLvCof(lv);
					var have=this.getNumById(cfg.itemid)
					if(lv<maxLv&&have>=parseInt(curLvCfg.item)){
						this.red.showRedPoint("zhanWen","sj"+dressInfo.dressGrid,RedTypeEnum.RoleOneMenuRed);
						bo=true;
					}
					else{
						this.red.hideRedPoint("zhanWen","sj"+dressInfo.dressGrid,RedTypeEnum.RoleOneMenuRed);
					}
				}
			}
			else{
				this.red.hideRedPoint("zhanWen","xq"+i,RedTypeEnum.RoleOneMenuRed);
				this.red.hideRedPoint("zhanWen","sj"+i,RedTypeEnum.RoleOneMenuRed);
				this.red.hideRedPoint("zhanWen","rp"+i,RedTypeEnum.RoleOneMenuRed);
				if(i<=this.minggeGrid){
					dressInfo=this.getDressInfoByGrid(i);
					if(!dressInfo){
						var checkList=Mgr.minggeMgr.checkHacCanEquip(true);
						var hasMingge=checkList.length>0;
						if(hasMingge){
							this.red.showRedPoint("zhanWen","xq"+i,RedTypeEnum.RoleOneMenuRed);
							bo=true;
						}
					}
					else{
						cfg=this.getMGCof(dressInfo.templateId);
						lv=dressInfo.level;
						curLvCfg=this.getMgLvCof(lv);
						if(lv<maxLv){
							var soulList=curLvCfg.typeSoul;
							var sleg=soulList.length;
							var needMingli=0;
							for(var j=0;j < sleg;j++){
								var arr=String(soulList[j]).split(":");
								if(cfg.quality==parseInt(arr[0])){
									needMingli=parseInt(arr[1]);
									break ;
								}
							}
							if(Mgr.minggeMgr.mingli>=needMingli){
								this.red.showRedPoint("zhanWen","sj"+dressInfo.dressGrid,RedTypeEnum.RoleOneMenuRed);
								bo=true;
							}
						}
						if(Mgr.minggeMgr.checkHacCanReplace(dressInfo)){
							this.red.showRedPoint("zhanWen","rp"+dressInfo.dressGrid,RedTypeEnum.RoleOneMenuRed);
							bo=true;
						}
					}
				}
			}
		}
	}
	
