	__proto.jinJieRi=function(vo){
		this.minCannotGet=null;
		this.minMayGet=null;
		this.nextReach=null;
		this.arrayData.length=0;
		var arra=this.table_jinjie.getAllItemByFiled("actId",vo.actId);
		var getRewardDic={};
		var len=vo.getRewardRecord.length;
		for (var k=0;k < len;k++){
			getRewardDic[vo.getRewardRecord[k].id]=vo.getRewardRecord[k].LingQueState;
		}
		this.jinJieRiTarget=arra[0].targetdes;
		this.jinJieRiTargetType=parseInt(arra[0].stepranktype);
		for(var j=0;j<arra.length;j++){
			if(parseInt(arra[j].ranktype)==vo.rankType){
				arra[j]["getReward"]=getRewardDic[parseInt(arra[j].id)];
				if(vo.stepranktype==1){
					var needNum=parseInt(arra[j].num);
					this.red.hideRedPoint("quanminchongbangchild",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
					this.red.hideRedPoint("jinjieri",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
					arra[j]["isRed"]=false;
					for (var i=0;i < vo.jieshuList.length;i++){
						this.jinJieRiPro=vo.jieshuList[i];
						if(vo.jieshuList[i] >=(parseInt(arra[j].step))){
							needNum--;
						}
						else{
							if(!this.nextReach){
								this.nextReach=arra[j];
							}
						}
						if(needNum==0 && getRewardDic[arra[j].id] !=2){
							arra[j]["isRed"]=true;
							this.red.showRedPoint("jinjieri",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
							this.red.showRedPoint("quanminchongbangchild",arra[j].id,RedTypeEnum.JinRiMuBiaoRed+"_");
							break ;
						}
					}
				}
				else{
					var curAllLevel=0;
					var len1=vo.jieshuList.length;
					for (var i2=0;i2 < len1;i2++){
						curAllLevel+=vo.jieshuList[i2];
						this.jinJieRiPro=vo.jieshuList[i2];
					}
					this.red.hideRedPoint("jinjieri",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
					this.red.hideRedPoint("quanminchongbangchild",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
					arra[j]["isRed"]=false;
					if(curAllLevel < parseInt(arra[j].step)){
						if(!this.nextReach){
							this.nextReach=arra[j];
						}
					}
					if(curAllLevel >=parseInt(arra[j].step)&& vo.getRewardRecord[j].LingQueState !=2){
						arra[j]["isRed"]=true;
						this.red.showRedPoint("jinjieri",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
						this.red.showRedPoint("quanminchongbangchild",arra[j].id,RedTypeEnum.JinRiMuBiaoRed);
					}
				}
				this.arrayData.push(arra[j]);
			}
		};
		var len3=this.arrayData.length;
		for (var i3=0;i3 < len3;i3++){
			if(this.arrayData[i3].getReward==0 && !this.minCannotGet){
				this.minCannotGet=this.arrayData[i3];
				break ;
			}
		}
		if(!this.minCannotGet){
			this.minCannotGet=this.arrayData[len3-1];
		}
		EventCenter.instance.event("updata_jinjieri");
	}
