	__proto.updateYuPeiRed=function(){
		if(!Mgr.guide.isOpen("ZhanDuiFrame")){
			return;
		}
		if(!this._model.myTeamInfo||this._model.myTeamInfo.id==0){
			this._red.hideRedPoint("YuPei","skillRed","YuPeiRed");
			this._red.hideRedPoint("YuPei","jinJieRed","YuPeiRed");
			return;
		};
		var info=this._model.yupeiInfo;
		if(!info)return;
		var ifJJRed=false;
		var ifSkillRed=false;
		var needNum=info.num-info.pro;
		var needId=info.cost;
		if(needId){
			var have=Mgr.bag.getBagMatCount(needId);
			if(have >=needNum){
				var xiaNeed=info.xiayizhi;
				var haveXy=Mgr.moneyMgr.getMoneyByType(19);
				if(haveXy>=xiaNeed*needNum){
					ifJJRed=true;
				}
			}
		}
		if(ifJJRed){
			this._red.showRedPoint("YuPei","jinJieRed","YuPeiRed");
		}
		else{
			this._red.hideRedPoint("YuPei","jinJieRed","YuPeiRed");
		};
		var arr=this._model.skillDc.array;
		var len=arr.length;
		for(var i=0;i<len;i++){
			var ele=arr[i];
			var stat=this.getSkillStat(ele);
			if(stat==2||stat==4){
				ifSkillRed=true;
				break ;
			}
		}
		if(ifSkillRed){
			this._red.showRedPoint("YuPei","skillRed","YuPeiRed");
		}
		else{
			this._red.hideRedPoint("YuPei","skillRed","YuPeiRed");
		}
	}
	
	__proto.getSkillStat=function(ele){
		var yuPeiinfo=this._model.yupeiInfo;
		if(!yuPeiinfo)return 1;
		var cof=ele.getCfgData();
		var yuPeiLv=yuPeiinfo.level;
		var info=ele.getValue("skillInfo");
		var curSkillLv=0;
		if(!info){
			curSkillLv=0;
		}
		else{
			curSkillLv=info.level;
		};
		var ifActive=curSkillLv!=0;
		var nextSkillCof=SkillManager.ins.getData(cof.skilId,false,curSkillLv+1);
		if(nextSkillCof){
			if(ifActive){
				var nextLvNeed=nextSkillCof.levelneed;
				var lvEnough=nextLvNeed <=yuPeiLv;
			}
			else{
				var activeNeed=parseInt(cof.yupeiLevel);
				lvEnough=activeNeed<=yuPeiLv;
			};
			var needItem=nextSkillCof.itemneed;
			var itemEngouh=Mgr.bag.checkItemIsEnough(needItem);
			var moneyType=nextSkillCof.moneyType;
			var moneyNeed=nextSkillCof.moneyNeed;
			if(moneyNeed&&moneyType){
				var have=Mgr.moneyMgr.getMoneyByType(moneyType);
				var moneyEnough=have>=moneyNeed;
			}
			else{
				moneyEnough=true;
			}
		}
		else{
			lvEnough=false;
			itemEngouh=false;
			moneyEnough=false;
		}
		if(ifActive){
			if(!lvEnough||!itemEngouh||!moneyEnough){
				return 3;
			}
			else{
				return 4;
			}
		}
		else{
			if(!lvEnough||!itemEngouh||!moneyEnough){
				return 1;
			}
			else{
				return 2;
			}
		}
	}
	
