	SkillBase.showGroupCircle=function(skillVO){
		var unit=skillVO.curObj;
		var skillName=skillVO.skillBottomRes;
		skillVO.scale=1;
		SkillBase.createSkillInMap(skillVO,skillName,unit.x,unit.y,skillVO.actKey,-1,0,0,1,1,false,0,false);
		var boci=4;
		var nums=12;
		var r=skillVO.rang;
		var deyTime=skillVO.delayTime;
		skillName=skillVO.skillUseRes;
		var tempAngle=360/nums;
		var bigAry=[];
		var smaAry=[];
		for (var i=0;i < 12;i++){
			var t=tempAngle *i;
			if((t % 90)==0){
				bigAry.push(t);
			}
			else{
				smaAry.push(t);
			}
		}
		for(var j=0;j < 4;j++){
			tempAngle=CommonUtil.angleToRadian(bigAry[j]);
			var offX=Math.sin(tempAngle)*r;
			var offY=Math.cos(tempAngle)*r;
			skillVO.scale=1;
			if(j==0){
				var laya=1;
			}
			else{
				laya=0;
			}
			SkillBase.createSkillInMap(skillVO,skillName,unit.x+offX,unit.y+offY,skillVO.actKey,-1,0,boci*deyTime,skillVO.looptimes,laya,false,0,false);
		}
		for(j=0;j < 8;j++){
			tempAngle=CommonUtil.angleToRadian(smaAry[j]);
			offX=Math.sin(tempAngle)*r;
			offY=Math.cos(tempAngle)*r;
			skillVO.scale=0.6;
			boci=Math.round(Math.random()*8)+4;
			if(j < 2 || j > 5){
				laya=1
			}
			else{
				laya=0;
			}
			SkillBase.createSkillInMap(skillVO,skillName,unit.x+offX,unit.y+offY,skillVO.actKey,-1,0,boci*deyTime,skillVO.looptimes,0,false,0,false);
		}
	}
	SkillBase.showFullScreenDU=function(skillVO,layer){
		(layer===void 0)&& (layer=1);
		var skillName=layer==1?skillVO.skillUseRes:skillVO.skillBottomRes;
		var mainPlayer=skillVO.curObj;
		var stageW=Laya.stage.width;
		var stageH=Laya.stage.height;
		var num=skillVO.nums;
		var qidianX=(stageW-7*150)>>1;
		var qidianY=mainPlayer.y+(stageH >>2);
		var firstnum=7;
		var jiange=150;
		var moveXY=150;
		for(var i=0;i< num;i++){
			for(var j=0;j<firstnum;j++){
				var tempQiDianY=qidianY+i *jiange+jiange *(Math.random()-0.5);
				var tempQiDianX=qidianX+j *moveXY+moveXY*(Math.random()-0.5);
				SkillBase.createSkillInMap(skillVO,skillName,tempQiDianX,tempQiDianY,0,-1,0,0,skillVO.looptimes,layer);
			}
			qidianY+=jiange;
		}
	}
	SkillBase.showFullScreenLURD=function(skillVO,layer){
		(layer===void 0)&& (layer=1);
		var skillName=layer==1?skillVO.skillUseRes:skillVO.skillBottomRes;
		var mainPlayer=skillVO.curObj;
		var stageW=Laya.stage.width;
		var stageH=Laya.stage.height;
		var num=skillVO.nums;
		var qidianX=mainPlayer.x-(stageW>>2);
		var qidianY=mainPlayer.y-(stageH >>2);
		var firstnum=1;
		var fengding=4;
		var jiange=300;
		var moveXY=jiange/1.4;
		var isAdd=true;
		for(var i=0;i< num;i++){
			var tempQiDianX=qidianX;
			var tempQiDianY=qidianY;
			var isOdd=firstnum%2==0;
			var offX=0;
			var offY=0;
			var flagX=1;
			var flagY=-1;
			for(var j=0;j<firstnum;j++){
				offX=j *moveXY *flagX;
				offY=j *moveXY *flagY;
				if(isOdd){
					offX+=(moveXY>>1);
					offY+=-(moveXY>>1);
				}
				tempQiDianX+=offX;
				tempQiDianY+=offY;
				flagX *=-1;
				flagY *=-1;
				SkillBase.createSkillInMap(skillVO,skillName,tempQiDianX,tempQiDianY,0,-1,0,0,skillVO.looptimes,layer);
			}
			qidianX-=moveXY;
			qidianY-=moveXY;
			if(firstnum >=fengding){
				isAdd=false;
				}else if(firstnum <=1){
				isAdd=true;
			}
			firstnum+=isAdd?1:-1;
		}
	}
	SkillBase.showDirectMulSector=function(skillVO,layer){
		(layer===void 0)&& (layer=1);
		var dir=skillVO.dirId;
		var angle=CommonUtil.angleToRadian(SkillBase.rotArr[dir]);
		var num=skillVO.nums;
		var distance=skillVO.radius;
		var rang=skillVO.rang;
		var sin=Math.sin(angle);
		var cos=Math.cos(angle);
		var delayTime=skillVO.delayTime;
		var data={};
		data.flagDic={};
		data.skillVO=skillVO;
		data.layer=layer;
		data.angle=angle;
		data.num=num;
		data.rang=rang;
		data.distance=distance;
		data.delay=delayTime;
		SkillBase.recursionShowSector(data,true,1,1,distance*cos,distance*sin);
	}
	SkillBase.recursionShowSector=function(data,isLeft,index,ceng,offX,offY){
		var skillVO=data.skillVO;
		var flagDic=data.flagDic;
		if(flagDic[index]){
			return;
		}
		flagDic[index]=1;
		var angle=data.angle;
		var layer=data.layer;
		var rang=data.rang;
		var delayTime=data.delay;
		var num=data.num;
		if(index==1){
			Laya.timer.once(0,SkillBase,SkillBase.laterShowDirectMul,[skillVO,layer,offX,offY],false);
			}else{
			var tempAngle=angle;
			if(isLeft){
				tempAngle-=CommonUtil.angleToRadian(30);
				}else{
				tempAngle+=CommonUtil.angleToRadian(30);
			};
			var sin=Math.sin(tempAngle);
			var cos=Math.cos(tempAngle);
			offX+=rang *cos;
			offY+=rang *sin;
			Laya.timer.once((ceng-1)*delayTime,SkillBase,SkillBase.laterShowDirectMul,[skillVO,layer,offX,offY],false);
		}
		if(ceng< num){
			SkillBase.recursionShowSector(data,true,index+ceng,ceng+1,offX,offY);
			SkillBase.recursionShowSector(data,false,index+ceng+1,ceng+1,offX,offY);
		}
	}
	SkillBase.showDirectMul=function(skillVO,layer){
		(layer===void 0)&& (layer=1);
		var dir=skillVO.dirId;
		var angle=CommonUtil.angleToRadian(SkillBase.rotArr[dir]);
		var num=skillVO.nums;
		var distance=skillVO.radius;
		var rang=skillVO.rang;
		var sin=Math.sin(angle);
		var cos=Math.cos(angle);
		var delayTime=skillVO.delayTime
		for(var i=0;i < num;i++){
			var totalDistance=distance+rang *i;
			if(skillVO.move==0){
				var offX=totalDistance*cos;
				var offY=totalDistance*sin;
				}else{
				offX=0;
				offY=0;
			}
			Laya.timer.once(delayTime*i,SkillBase,SkillBase.laterShowDirectMul,[skillVO,layer,offX,offY,SkillBase.rotArr[dir]],false);
		}
	}
	SkillBase.laterShowDirectMul=function(skillVO,layer,offX,offY,angle){
		var skillName=layer==1?skillVO.skillUseRes:skillVO.skillBottomRes;
		var unit=skillVO.curObj;
		var unitX=unit.x;
		var unitY=unit.y;
		var ani=SkillBase.createSkillInMap(skillVO,skillName,unitX+offX,unitY+offY,skillVO.actKey,-1,angle,0,skillVO.looptimes,layer,false,0,false);
	}
	SkillBase.showFullScreen=function(skillVO,layer){
		(layer===void 0)&& (layer=1);
		var offsetX=100;
		var offsetY=100;
		var mainPlayer=skillVO.curObj;
		var skillName=layer==1 ? skillVO.skillUseRes:skillVO.skillBottomRes;
		var xCount=4;
		var yCount=2;
		var arr=[];
		var ranArr=[];
		for(var i=0;i<xCount;i++){
			for(var k=0;k<yCount;k++){
				arr.push([i,k]);
			}
		};
		var len=arr.length;
		while(len>0){
			var ranindex=Math.floor(Math.random()*len);
			var areaId=arr.splice(ranindex,1)[0];
			ranArr.push(areaId);
			len=arr.length;
		};
		var senceW=Laya.stage.width;
		var senceH=Laya.stage.height;
		var mapW=SceneContainer.getInstance().upMapLayer.mapWidth;
		var mapH=SceneContainer.getInstance().upMapLayer.mapHeigth;
		var minX=(mainPlayer.x-((senceW)>>1))> 0 ? mainPlayer.x-(senceW>>1):0;
		var minY=mainPlayer.y-(senceH>>1)> 0 ? mainPlayer.y-(senceH>>1):0;
		var rightX=0;
		var rightY=0;
		if((mapW-mainPlayer.x)<(senceW>>1)){
			rightX=mapW-senceW;
		}
		else{
			rightX=minX;
		}
		if((mapH-mainPlayer.y)<(senceH>>1)){
			rightY=mapH-senceH;
		}
		else{
			rightY=minY;
		};
		var count=skillVO.nums;
		for(var j=0;j<count;j++){
			var tempIndex=j%(xCount*yCount);
			var areaArr=ranArr[tempIndex];
			var randomX=(Laya.stage.width>>2)*(areaArr[0]%xCount)+rightX+(Laya.stage.width>>2)*Math.random()+offsetX;
			var randomY=(Laya.stage.height>>1)*(areaArr[1]%yCount)+rightY+(Laya.stage.height>>1)*Math.random()+offsetY;
			var randomTime=j*skillVO.delayTime;
			Laya.timer.once(randomTime,SkillBase,SkillBase.createSkillInMap,[skillVO,skillName,randomX,randomY,0,-1,0,0,1,layer,false,0,false,skillVO.selfPanel],false);
		}
	}
