	SkillBase.showRush=function(skillvo){
		var unit=skillvo.curObj;
		var dis=skillvo.actVo.rushDis;
		var speed=skillvo.actVo.rushSpeed;
		var dir=unit.curDir;
		var angle=CommonUtil.angleToRadian(SkillBase.rotArr[dir]);
		var offx=Math.cos(angle)*dis+unit.x;
		var offy=Math.sin(angle)*dis+unit.y;
		var ary=SceneContainer.getInstance().getWalkPo(offx,offy);
		offx=ary[0];
		offy=ary[1];
		var times=dis / speed;
		times=times > 120? times :120;
		if((unit instanceof com.xq.rpg.unit.MainPlayer )){
			EventCenter.instance.event("SEND_PLAYER_MOVE",[unit,[[offx,offy]],true,true]);
		}
		unit.ghost(true);
		unit.doAction(6,unit.curDir,true);
		Tween.to(unit,{x:offx,y:offy},times,null,Handler.create(SkillBase,com.xq.rpg.skill.SkillBase.runEnd,[unit]));
	}
