	__proto.checkByFanJiType=function(unitArr,nArr,atackUnit){
		var hasPlayer=false;
		var len=unitArr.length;
		var unit;
		for(var i=0;i < len;i++){
			unit=unitArr[i];
			if(!unit.isEnemy)
				continue ;
			if((unit instanceof com.xq.rpg.unit.Player )){
				hasPlayer=true;
				break ;
			}
		}
		for(var i=0;i < len;i++){
			unit=unitArr[i];
			if(!unit.isEnemy || (unit instanceof com.xq.rpg.unit.SubPlayer )|| (unit instanceof com.xq.rpg.unit.RobotSubPlayer ))
				continue ;
			if(atackUnit){
				if(atackUnit==unit){
					continue ;
				};
				var tempVo=atackUnit.vo;
				if(tempVo && tempVo.parentPlayerID==unit.guid){
					continue ;
				}
			}
			if(hasPlayer){
				if((unit instanceof com.xq.rpg.unit.Player ))
					nArr.push(unit);
				}else{
				if((unit instanceof com.xq.rpg.unit.Monster ))
					nArr.push(unit);
			}
		}
		return nArr;
	}
	
	__proto.checkActiveUnit=function(unitArr,attackUnit){
		var type=SettingAction.ins().pkModel;
		var len=unitArr.length;
		var nArr=[];
		var playerVo=NetMgr.ins().roleVO;
		var isEney=attackUnit.isEnemy;
		if(type==6){
			return this.checkByFanJiType(unitArr,nArr,attackUnit);
		}
		for(var i=0;i < len;i++){
			var unit=unitArr[i];
			if(!unit || (unit instanceof com.xq.rpg.unit.SubPlayer )|| (unit instanceof com.xq.rpg.unit.RobotSubPlayer )){
				continue ;
			}
			if(attackUnit){
				if(attackUnit==unit){
					continue ;
				};
				var tempVo=attackUnit.vo;
				if(tempVo && tempVo.parentPlayerID==unit.guid){
					continue ;
				}
			}
			if(!unit.isEnemy && !RobotPlayerMgr.ins.RobotIsEney)
				continue ;
			if(unit.isEnemy==isEney && !attackUnit.isAttackAll){
				continue ;
			}
			if((unit instanceof com.xq.rpg.unit.Monster )){
				nArr.push(unit)
			}
			else{
				switch(type){
					case 0:
						break ;
					case 2:
						if((unit instanceof com.xq.rpg.unit.Player )){
							var vo=unit.vo;
							if(playerVo.guildId==0 || vo.guildId !=playerVo.guildId){
								if(vo.parentPlayerID){
									var payer=UnitManager.ins.getPlayerByRoleID(vo.parentPlayerID);
									if(payer){
										var payVo=payer.vo;
										if(payVo.guildId==0 || payVo.guildId !=playerVo.guildId){
											nArr.push(unit);
										}
									}
								}
								else{
									nArr.push(unit);
								}
							}
						}
						break ;
					case 3:
						nArr.push(unit);
						break ;
					case 4:
						break ;
					case 5:
						if((unit instanceof com.xq.rpg.unit.Player )){
							vo=unit.vo;
							if((attackUnit.vo).num28 !=vo.num28)
								nArr.push(unit);
						}
						break ;
					}
			}
		}
		return nArr;
	}
