	__proto.offArm=function(curUnit,vo){
		var offx=Math.round(0.5*vo.length);
		var offinit=Math.round(0.5*(vo.rang >> 1));
		var realx=curUnit.x;
		var realy=curUnit.y;
		var ary=[]
		switch(curUnit.curDir){
			case 0:
				ary[0]=realx-(vo.rang>>1);
				ary[1]=realy+vo.length;
				break ;
			case 1:
				ary[0]=realx-offinit+offx;
				ary[1]=realy+offinit+offx;
				break ;
			case 2:
				ary[0]=realx+vo.length;
				ary[1]=realy+(vo.rang>>1);
				break ;
			case 3:
				ary[0]=realx+offinit+offx;
				ary[1]=realy+offinit-offx;
				break ;
			case 4:
				ary[0]=realx+(vo.rang>>1);
				ary[1]=realy-vo.length;
				break ;
			case 5:
				ary[0]=realx+offinit-offx;
				ary[1]=realy-offinit-offx
				break ;
			case 6:
				ary[0]=realx-vo.length;
				ary[1]=realy-(vo.rang>>1);
				break ;
			case 7:
				ary[0]=realx-(vo.rang >> 1)
				ary[1]=realy-(vo.rang >> 1)+offx;
				break ;
			}
		return ary;
	}
