	__proto.harm=function(vo){
		if(!UnitManager.harmMgr){
			UnitManager.harmMgr=new HarmManager();
		};
		var attacker=this._unitList.get(vo.attackerId);
		if(!attacker){
			return;
		};
		var len=vo.harmMsgs.length;
		for(var i=0;i < len;i++){
			var msg=vo.harmMsgs[i];
			var target=this._unitList.get(msg.targetId);
			if(!target){
				continue ;
			}
			if((target instanceof com.xq.rpg.unit.MainPlayer )){
				(target).onBeAttacked(attacker);
			};
			var dir=CommonUtil.changeDir(attacker.x,attacker.y,target.x,target.y);
			var skillVo=SkillManager.ins.getData(vo.skillCategory);
			if(skillVo && skillVo.harmcount.length){
				var timeArr=skillVo.harmcount;
				var n=timeArr.length;
				var v=Math.floor(msg.harmValue/n);
				var delay=10;
				for(var j=0;j < n;j++){
					delay+=parseInt(timeArr[j]);
					Laya.timer.once(delay,UnitManager.harmMgr,UnitManager.harmMgr.hurt,[msg.harmType,v,target,dir,0],false);
				}
			}
			else{
				Laya.timer.once(30,UnitManager.harmMgr,UnitManager.harmMgr.hurt,[msg.harmType,msg.harmValue,target,dir,0],false);
			}
		}
	}
	
	__proto.checkHitOut=function(skillVo,target,attacker,isDead){
		var distance=0;
		if(skillVo){
			var r=Math.atan2(target.y-attacker.y,target.x-attacker.x);
			if(isDead){
				distance=skillVo.jf-target.vo.jfkx;
				if(distance<=0)
					distance=0;
				else
				distance *=target.vo.hitoffset;
			}
			else{
				distance=skillVo.jt-target.vo.jtkx;
				if(distance<=0)
					distance=0;
				else
				distance *=target.vo.hitoffset;
			};
			var dx=target.x+distance*Math.cos(r);
			var dy=target.y+distance*Math.sin(r);
			var now=ServerTimeAction.ins().serverTimer;
			if(SceneContainer.getInstance().isCanWalkable(dx,dy)&& Math.abs(this.lastTime-now)>20000){
				this.lastTime=now;
				SceneSynAction2.ins().sendRepelMonster(dx,dy,target.guid);
			}
		}
		return distance;
	}
	
