	__proto.getNearEney=function(curObj,type,dis,isRandom){
		(type===void 0)&& (type=0);
		(dis===void 0)&& (dis=750);
		(isRandom===void 0)&& (isRandom=false);
		var arr;
		switch(type){
			case 0:arr=this.monsterList.values;break ;
			case 1:arr=this.roleList.values;break ;
			case 2:arr=this._unitList.values;break ;
			}
		arr=this.sortUnit(curObj.x,curObj.y,arr,30,dis);
		var isEney=curObj.isEnemy;
		var unit;
		var l=arr.length;
		if(isRandom){
			for (var i=0;i < l;i++){
				unit=arr[i];
				if(!unit.isDead&& unit !=curObj){
					return unit;
				}
			}
			}else{
			for (var i=0;i < l;i++){
				unit=arr[i];
				if(isEney==unit.isEnemy || unit.isDead){
					continue ;
				}
				else{
					return unit;
				}
			}
		}
		return null;
	}
	
	__proto.getNearEnemys=function(dis){
		(dis===void 0)&& (dis=750);
		var tagetArr=[];
		var player=Model.game.mPlayer;
		var arr=this.roleList.values;
		arr=this.sortUnit(player.x,player.y,arr,10,dis);
		var len=arr.length;
		var unit;
		for(var i=0;i<len;i++){
			unit=arr[i];
			if((unit instanceof com.xq.rpg.unit.MainPlayer )|| (unit instanceof com.xq.rpg.unit.SubPlayer )){
				continue ;
			}
			if(unit.isEnemy){
				tagetArr.push(unit.vo);
			}
		}
		arr=this.monsterList.values;
		arr=this.sortUnit(player.x,player.y,arr,10-len,dis);
		len=arr.length;
		for(i=0;i<len;i++){
			unit=arr[i];
			tagetArr.push(unit.vo);
		}
		return tagetArr;
	}
	
	__proto.getNearestUnit=function(curObj,type,dis,lockMonster){
		(type===void 0)&& (type=0);
		(dis===void 0)&& (dis=600);
		var arr;
		switch(type){
			case 0:arr=this.monsterList.values;break ;
			case 1:arr=this.roleList.values;break ;
			case 2:arr=this._unitList.values;break ;
			}
		arr=this.sortUnit(curObj.x,curObj.y,arr,20,dis);
		var unit;
		var len=arr.length;
		for(var i=0;i < len;i++){
			unit=arr[i];
			if(!unit)continue ;
			if(unit==curObj)continue ;
			if((unit instanceof com.xq.rpg.unit.Monster )|| (unit instanceof com.xq.rpg.unit.Player )){
				this.targetMgr.changeState(unit);
				if(!unit.isEnemy)
					continue ;
				if(unit.guid==(curObj.vo).parentPlayerID){
					continue
				}
				if(lockMonster==null){
					return unit;
				}
				else{
					var monsterId=unit&& (unit instanceof com.xq.rpg.unit.Monster )&&unit.vo?(unit.vo).monsterId:"";
					if(monsterId==lockMonster){
						return unit;
					}
				}
			}
		}
		return null;
	}
	
	__proto.getRandomTar=function(tar){
		var pos
		if(!pos){
			pos=new Point();
		};
		var diffX=0;
		var diffY=0;
		var tempX=Math.random()*200;
		var tempY=Math.random()*200;
		var tempRollX=Math.random()*2;
		var tempRollY=Math.random()*2;
		if(tempRollX<1){
			diffX=tempX;
		}
		else{
			diffX=-tempX;
		}
		if(tempRollY<1){
			diffY=tempY;
		}
		else{
			diffY=-tempY;
		}
		pos.x=tar.x+diffX;
		pos.y=tar.y+diffY;
		return pos;
	}
	__proto.sortUnit=function(sx,sy,targetArr,nums,dis){
		var finalArr=[];
		var flagArr=[];
		var len=targetArr.length;
		if(len==0)
			return [];
		if(nums>len)
			nums=len;
		var minDis=NaN;
		var tarObj;
		var startX=sx;
		var startY=sy;
		var endX=0;
		var endY=0;
		var flag=0;
		for(var j=0;j <nums;j++){
			flag=-1;
			minDis=99999;
			for(var i=0;i < len;i++){
				if(flagArr[i]==1)
					continue ;
				tarObj=targetArr[i];
				if(!tarObj || (tarObj instanceof com.xq.rpg.unit.SubPlayer )|| (tarObj instanceof com.xq.rpg.unit.RobotSubPlayer )|| tarObj.isDead)
					continue ;
				this.targetMgr.changeState(tarObj);
				if((!tarObj.isEnemy)){
					if(tarObj.isDispose){
						continue ;
					}
					if((tarObj instanceof com.xq.rpg.unit.MainPlayer )==false){
						continue
					}
					else if(!RobotPlayerMgr.ins.RobotIsEney){
						continue
					}
				}
				endX=tarObj.x;
				endY=tarObj.y;
				var tempDis=CommonUtil.getDistance(startX,startY,endX,endY);
				if(tempDis > dis)
					continue ;
				if(minDis > tempDis){
					flag=i;
					minDis=tempDis;
				}
			}
			if(flag !=-1){
				flagArr[flag]=1;
				finalArr.push(targetArr[flag]);
			}
			else{
				break ;
			}
		}
		return finalArr;
	}
	
	__proto.getNearestMonster=function(monsterid){
		var minLen=20000000;
		var currentMonster=null;
		var dx=0,dy=0,squarelen=0;
		var mainAvatar=Model.game.mPlayer;
		var monster;
		for(var $each_monster in this.monsterList.values){
			monster=this.monsterList.values[$each_monster];
			if((monster.vo).monsterId==monsterid){
				dx=mainAvatar.x-monster.x;
				dy=mainAvatar.y-monster.y;
				squarelen=Math.sqrt(dx *dx+dy *dy);
				if(squarelen < minLen){
					currentMonster=monster;
					currentMonster.dis=squarelen;
					minLen=squarelen;
				}
			}
		};
		var monRobot=null;
		if(!currentMonster){
			var monster2;
			for(var $each_monster2 in this._robotList){
				monster2=this._robotList[$each_monster2];
				dx=mainAvatar.x-monster2.x;
				dy=mainAvatar.y-monster2.y;
				squarelen=Math.sqrt(dx *dx+dy *dy);
				if(squarelen < minLen){
					monRobot=monster2;
					monRobot.dis=squarelen;
					minLen=squarelen;
				}
			}
			return monRobot;
		}
		return currentMonster;
	}
