	__proto.getNearestColloct=function(collectId){
		var mainPlayer=Model.game.mPlayer;
		var minLen=20000000;
		var currentCollect;
		var collect;
		for(var $each_collect in this.collectList.values){
			collect=this.collectList.values[$each_collect];
			if(collect){
				var vo=collect.vo;
				if(vo.state==0){
					if(collectId==null || vo.id==collectId){
						var dx=mainPlayer.x-collect.x;
						var dy=mainPlayer.y-collect.y;
						var squarelen=dx *dx+dy *dy;
						if(squarelen < minLen){
							currentCollect=collect;
							minLen=squarelen;
						}
					}
				}
			}
		}
		if(currentCollect)currentCollect.distance=minLen;
		return currentCollect;
	}
