	CommonUtil.getAtrData=function(ary,_cloName,_cloVal,isZero,moduleStr,isXN,isShowRad){
		(_cloName===void 0)&& (_cloName="");
		(_cloVal===void 0)&& (_cloVal="");
		(isZero===void 0)&& (isZero=false);
		(moduleStr===void 0)&& (moduleStr="");
		(isXN===void 0)&& (isXN=false);
		(isShowRad===void 0)&& (isShowRad=false);
		var tempAry=[];
		var len=ary.length;
		for (var i=0;i < len;i++){
			var vo=ary[i]
			if(isXN&&vo.attrId==17){
				continue ;
			};
			var obj={};
			if(isShowRad&&vo["rad"] >=0){
				obj.attrName=com.xq.util.CommonUtil.getAtrName(vo["rad"]);
				obj.attrId=vo["rad"];
			}
			else{
				obj.attrName=com.xq.util.CommonUtil.getAtrName(vo.attrId);
				obj.attrId=vo.attrId;
			}
			obj.sortFlag=AttrEnum.getFlag(vo.attrId);
			if(!isZero){
				if(vo["teShuAttrValue"]){
					obj.attrVal=vo["teShuAttrValue"];
					}else{
					obj.attrVal=vo.attrValue;
				}
				}else{
				obj.attrVal=0;
			}
			obj.cloName=_cloName;
			obj.cloVal=_cloVal;
			obj.moduleStr=moduleStr;
			tempAry.push(obj);
		};
		var sortFun=function (a,b){
			return a.sortFlag-b.sortFlag
		}
		tempAry.sort(sortFun);
		return tempAry;
	}
