			img.skin=PathDefine.RES2_ROOT+PathDefine.DROP_ICON+"item"+".png";
			img.x=x;
			img.y=y;
			Model.game.sceneContainer.unitLayer.addChild(img);
			var flag=i%2==0?-1:1;
			var randomY=-(Math.round(Math.random()*100)+20)+y;
