	__proto.doCheckYulan=function(){
		var yulanDic=Mgr.guide.guideModel.yuLanDic;
		if(!Mgr.task.curTask)return;
		var taskData=this.guideModel.getYuLanByTask();
		var lvData=this.guideModel.getYuLanByLevel();
		var gqData=this.guideModel.getYuLanByPass();
		var dayData=this.guideModel.getYuLanByOpenDay();
		var taskInx=taskData ? yulanDic.indexOf(taskData.id):-1;
		var levelInx=lvData ? yulanDic.indexOf(lvData.id):-1;
		var gqInx=gqData ? yulanDic.indexOf(gqData.id):-1;
		var dayInx=dayData ? yulanDic.indexOf(dayData.id):-1;
		var yulanData;
		var ary=[taskInx,levelInx,gqInx,dayInx];
		var minInx=CommonUtil.getMinNum(ary,-1);
		if(minInx==0){
			yulanData=taskData;
		}
		else if(minInx==1){
			yulanData=lvData;
		}
		else if(minInx==2){
			yulanData=gqData;
		}
		else if(minInx==3){
			yulanData=dayData;
		}
		if(!yulanData){
			if(this.guideModel.hasYuLanRed){
				if(this.guideModel.lastObj){
					var sIcon=this.guideModel.lastObj.source1;
				}
				else{
					sIcon="xilian";
				}
				this.openYulan({value:-1,source1:sIcon,showValue:"功能奖励"});
			}
			else{
				this.closeYulan();
			}
		}
		else if(yulanData){
			this.openYulan(yulanData);
		}
		else{
			this.closeYulan()
		}
	}
