	__proto.onSceneCreateRole=function(b){
		if(!this.myRoleVo){
			this.myRoleVo=NetMgr.ins().roleVO;
		};
		var vo=new CreatePlayerInStageSC();
		vo.decode(b);
		var roleArr=vo.players;
		var len=roleArr.length;
		var container=Game.getInstance().sceneContainer;
		if(!this.mainPlayer){
			this.mainPlayer=Game.getInstance().player;
		}
		for(var i=0;i< len;i++){
			var roleVo=new RoleVO();
			roleVo.bind(roleArr [i]);
			if(roleVo.parentPlayerID==this.mainPlayer.guid){
				roleVo.isMySubRole=true;
			}
			if(this.myRoleVo&&MapType.isHideSubplayer(this.myRoleVo.mapType)&&(roleVo.isSubPlayer||roleVo.isRobotSubpl)){
				return;
			};
			var hadRole=false;
			if(UnitManager.ins.roleList.get(roleVo.guid)){
				hadRole=true;
			};
			var role=UnitManager.ins.createRole(roleVo);
			if(role){
				if(hadRole && role !=this.mainPlayer){
					role.updateVO(roleVo,this.mainPlayer);
					this.unitManager.setResource(role);
				}
				container.unitLayer.addChild(role);
				Game.getInstance().addUnit(role);
			}
			if((role instanceof com.xq.rpg.unit.SubPlayer )&& !hadRole){
				Mgr.subPlayer.regSubPlayer(role);
				if(NetMgr.ins().roleVO.mapType==52){
					role.pos(this.mainPlayer.x,this.mainPlayer.y);
				}
			}
			if((role instanceof com.xq.rpg.unit.RobotPlayer )){
				Mgr.skillGroup.initRobotPlayerSkill(role);
				(role).startAI();
			}
		}
	}
