	__proto.sendPlayerMove=function(activeUnit,path,isActiveMove,isMust){
		if(Game.getInstance().player.isInSinCopy)
			return
		if(activeUnit.vo && Math.abs(this.lastMoveTime-Mgr.curTime.serverTimer)> 3000 || isMust){
			if(path==null || path.length==0){
				return;
			}
			this.lastMoveTime=Mgr.curTime.serverTimer;
			var pvo=new PlayerMoveCSC();
			pvo.faceto=activeUnit.curDir;
			pvo.moverId=activeUnit.vo.guid;
			pvo.step=0;
			this.parr.length=0;
			pvo.pathPoints=this.parr;
			pvo.isActiveMove=isActiveMove;
			var len=path.length;
			for(var i=0;i < len;i++){
				var pmsg=new PointMsg();
				var arr=SceneContainer.GlobalToGrid(path[i][0],path[i][1]);
				pmsg.x=arr[0];
				pmsg.y=arr[1];
				this.parr.push(pmsg);
			};
			var firstPos=this.parr[this.parr.length-1];
			pvo.x=firstPos.x;
			pvo.y=firstPos.y;
			this._net.sendMsg(8840000,pvo);
		}
	}
