	__proto.onUnitDead=function(b){
		var vo=new DeadSC();
		vo.decode(b);
		this.unitManager.dead(vo);
		if(vo.deaderGuid==this._net.roleVO.guid){
			var map=this.mapLineCfgData.getItemByField("mapid",this._net.roleVO.mapId);
			EventCenter.instance.event(GameEvent.MAINPLAYER_DEAD);
			console.log("主角死亡===============mapid="+this._net.roleVO.mapId)
			var mainPlayer=Game.getInstance().player;
			var maptype=parseInt(map.maptype);
			var v;
			switch(maptype){
				case 45:{
						Laya.timer.once(5000,Mgr.skillPro,Mgr.skillPro.sendHuiChengFuhuo);
						break ;
					}
				case 1:{
						v=UIMgrR.openIView(com.xq.view.modules.fuhuo.IFuHuoView,2);
						v.dataSource=vo;
						break ;
					}
				case 51:{
						break ;
					}
				case 11:{
						break ;
					}
				case 16:{
						break ;
					}
				case 54:{
						Mgr.ggzjMgr.showReliveTip(vo.attackerName);
						break ;
					}
				case 49:{
						break ;
					}
				case 63:{
						EventCenter.instance.event("updateCopyInfo");
					}
				case 66:{
						break ;
					}
				case 73:{
						break ;
					}
				case 67:{
						v=UIMgrR.openIView(com.xq.view.modules.zhanDuiJingJi.IXiaYiFuHuoView,2);
						v.dataSource=vo;
						break ;
					}
				case 69:
				case 70:{
						var fhdV=UIMgrR.openIView(com.xq.view.modules.fuhuo.IFuHuoDianFuHuoView,2);
						fhdV.setData(vo.attackerName,"己方复活点复活");
						break ;
					}
				default :{
						if(map.borntimes && map.borntimes > mainPlayer.reviveTimes){
							v=UIMgrR.openIView(com.xq.view.modules.fuhuo.IFuHuoView,2);
							v.dataSource=vo;
							mainPlayer.reviveTimes++;
						}else{}
						break ;
					}
				}
		}
		else {
			var deadUni=this.unitManager.unitList.get(vo.deaderGuid);
			var attacUni=this.unitManager.unitList.get(vo.attackerGuid);
			if(deadUni){
				if((deadUni instanceof com.xq.rpg.unit.SubPlayer ))
					Mgr.subPlayer.checkSubPlayerDead(vo.deaderGuid);
				else if(attacUni && (deadUni instanceof com.xq.rpg.unit.Monster )){}
			}
		}
	}
	
