	__proto.onBuyVipShop=function(b){
		var msg=new BuyVipGoodSC();
		msg.decode(b);
		if(msg.errorCode==1){
			Mgr.prompt.optionPrompt("购买成功");
			var len=this.vipShopInfoArr.length;
			for (var i=0;i < len;i++){
				if(this.vipShopInfoArr[i].shangpinId==msg.goods.shangpinId){
					this.vipShopInfoArr[i]=msg.goods;
					break ;
				}
			}
			this.updateVipStoreList();
		}
		else{
			Mgr.prompt.optionPrompt(CodeMgr.ins.getStringByCode(msg.errorCode));
		}
	}
	__proto.updateVipStoreList=function(){
		var vipShopArr=Mgr.vip.vipStoreCfg.objectDataArray;
		var tempAry=[];
		var showRed=false;
		if(this.vipShopInfoArr){
			var len=this.vipShopInfoArr.length;
			var gmFlag=100;
			var vipFlag=50;
			var iniFlag=0;
			for (var i=0;i < len;i++){
				var tempObj=vipShopArr[i];
				if(!tempObj)
					continue ;
				var vipShopChild=this.vipShopInfoArr[i];
				tempObj["vipShopInfo"]=vipShopChild;
				tempAry[i]=tempObj;
				if((vipShopChild.xianGouCount-vipShopChild.yiGouCount)==0){
					tempObj["getReward"]=gmFlag++;
				}
				else{
					if(tempObj.viptype=="0"){
						if(Model.vip.vipData&& Model.vip.vipData.normalVipLevel < vipShopChild.vipLevel){
							tempObj["getReward"]=vipFlag++;
						}
						else{
							tempObj["getReward"]=iniFlag++;
							if(vipShopChild.xianJia==0){
								showRed=true;
							}
						}
					}
					else{
						if(NetMgr.ins().roleVO.vipLevel < vipShopChild.vipLevel){
							tempObj["getReward"]=vipFlag++;
						}
						else{
							tempObj["getReward"]=iniFlag++;
							if(vipShopChild.xianJia==0){
								showRed=true;
							}
						}
					}
				}
			}
			if(showRed){
				Mgr.red.showRedPoint("vipStore","default","StoreFreeExhchange");
			}
			else{
				Mgr.red.hideRedPoint("vipStore","default","StoreFreeExhchange");
			}
			EventCenter.instance.event("updata_vip_shop",[tempAry]);
		}
	}
	
