	__proto.enterScene=function(sceneId,posX,posY){
		if(this.curTran){
			this.curTran.readyDestory();
			this.curTran=null;
		}
		if(this.lastMapId !=sceneId){
			if(this.mapSpecial){
				this.mapSpecial.dispose();
				this.mapSpecial=null;
			}
			CopyTipMgr.ins.checkGc(sceneId);
			this.mapSpecial=MapSpecialFactory.getMapEffect(sceneId);
			if(this.mapSpecial){
				this.mapSpecial.preEnter();
			}
			if(MapIdEnum.checkIsGuanQia(this.lastMapId)&& this.lastGuaJIMap==sceneId){
				this.curTran=UIMgrR.newInstanceByIClass(com.xq.view.loading.ITransitCloudView);
				this.curTran.init();
			}
			else if(MapIdEnum.checkIsGuanQia(sceneId)){
				this.lastGuaJIMap=this.lastMapId;
				this.lastMapId=sceneId;
				this.curTran=UIMgrR.newInstanceByIClass(com.xq.view.loading.ITransitCloudView);
				this.curTran.init(false);
			}
			else{
				this.curTran=UIMgrR.newInstanceByIClass(com.xq.view.loading.ITransitPreloadingView);
			}
			if(this.lastMapId==-1){
				this.curTran.firstInit();
			}
			this.curTran.once("complete",this,this.onEnterLoadCom,[posX,posY,sceneId]);
			this.curTran.loadPreMapRes(sceneId,posX,posY);
			if(Laya.__typeof(this.curTran,'com.xq.view.loading.ITransitCloudView')&& !this.newMainView.visible){
				this.uiLayerBottom.addChild(this.curTran);
			}
			else{
				Laya.stage.addChild(this.curTran);
			}
			this.isOnceTran=true;
		}
		else{
			this.cleanUp();
			this.onEnterLoadCom(posX,posY,sceneId);
		}
	}
	
	__proto.addUnit=function(unit){
		if(this.mapSpecial){
			if((unit instanceof com.xq.rpg.unit.Monster ))
				this.mapSpecial.onMonsterEnter(unit);
			else if((unit instanceof com.xq.rpg.unit.Player ))
			this.mapSpecial.onPlayerEnter(unit);
		}
	}
	
	__proto.exitScene=function(){
		if(this.mapSpecial){
			this.mapSpecial.onExit();
		}
		this.clearEntePlay();
	}
	
	__proto.cleanUp=function(){
		if(this.sceneContainer)
			this.sceneContainer.cleanUp();
		Mgr.transfer.clear();
		AIController.ins().stop();
		Mgr.npc.clear();
		Mgr.jiGuan.clear();
		CollectMgr.ins().clear();
		Mgr.targetSelected.clearSelect(true);
		EventCenter.instance.event("EXIT_SCENE");
		UnitManager.ins.cleanUp();
		SkillManager.ins.cleanUp();
		Mgr.copy.clearWanXianMonster();
		UnitManager.ins.destoryAllTomb();
		Mgr.robot.clearPeiPao();
		if(this.player){
			this.player.ChangeMoveState(false);
		}
		AmtMgr.GC(false);
		if(Browser.onWeiXin){
			(typeof(wx)!='undefined')&& wx.triggerGC();
		}
	}
	__proto.onEnterLoadCom=function(posX,posY,sceneId){
		if(this.player){
			this.isOnEnter=true;
			this.point=SceneContainer.GridToGlobal(posX,posY);
			console.log("============================收到后端的地址::",posX,posY,sceneId,"---像素位置：",this.point[0],this.point[1]);
			var tempType=SceneContainer.getInstance().getMapTypeById(sceneId);
			if(sceneId !=this.lastMapId && !MapIdEnum.checkIsGuanQia(sceneId)){
				if(this.mapSpecial){
					this.mapSpecial.onEnter(this.point[0],this.point[1]);
				}
				this.lastMapId=sceneId;
				if(Mgr.transfer.standHites && this.firstLogin&&!com.xq.Game.getInstance().player.isDead){
					if(!this.player.isInSinCopy){
						this.player.x=this.point[0]-this.vWidth;
						this.player.y=this.point[1]-this.vHeight;
						Mgr.sceneSyn.enterPlayerTiao=Handler.create(this,this.enterIntoplay);
					}
					else{
						EventCenter.instance.event("UPDATE_ALONECOPY_POS");
					}
				}
				else{
					if(!this.player.isInSinCopy){
						this.player.x=this.point[0];
						this.player.y=this.point[1];
					}
					else{
						EventCenter.instance.event("UPDATE_ALONECOPY_POS");
					}
					this.player.updatePos();
				}
			}
			else{
				this.lastMapId=sceneId;
				if(this.mapSpecial){
					this.mapSpecial.onEnterAgain(this.point[0],this.point[1]);
				}
				Mgr.sceneSyn.enterPlayerTiao=null;
			}
			if(com.xq.Game.getInstance().player.isDead){
				this.player.revive();
			}
		}
		else{
			this.checkIsEnter();
			this.lastMapId=sceneId;
		}
		this.firstLogin=true;
		this.exeSceneComple();
	}
	__proto.exeSceneComple=function(){
		this.sceneContainer.mapCamera.start();
		EventCenter.instance.event("MAP_LOAD_OK");
		Mgr.sceneSyn.sendEnterStage();
	}
	__proto.enterIntoplay=function(){
		Mgr.sceneSyn2.sendSynPosition(this.point[0],this.point[1],true);
		if(this.player){
			this.player.isForbit=true;
		}
		if(this.curTran){
			this.curTran.readyDestory();
			this.curTran=null;
		}
		Laya.timer.frameOnce(1,this,this.laterenterIntoplay);
	}
	
	__proto.clearEntePlay=function(){
		Laya.timer.clear(this,this.laterenterIntoplay);
	}
	__proto.laterenterIntoplay=function(){
		if(this.player){
			this.player.x=this.point[0]-this.vWidth;
			this.player.y=this.point[1]-this.vHeight;
			console.log("跳跃之前，复位一次")
			this.player.isForbit=false;
			if(!this.player.isInSinCopy){
				this.player.flyingShose(2,null,this.point[0],this.point[1],Handler.create(this,this.endTiaoTween));
			}
		}
	}
	__proto.endTiaoTween=function(){
		Mgr.sceneSyn2.sendSynPosition(this.player.x,this.player.y);
		this.player.stand();
		Mgr.task.flyCompleteDoTask(Mgr.transPro.taskType);
	}
	__proto.getViewInfoObject=function(view,mapArr){
		var obj=new Object();
		obj["view"]=view;
		var len=28;
		for(var i=1;i <=len;i++){
			obj[i]=0;
		}
		len=mapArr.length;
		for(i=0;i < len;i++){
			obj[mapArr[i]]=1;
		}
		return obj;
	}
