	__proto.parserCfg=function(d,url,index){
		var per=((17 *(index-1)+index*Math.random()*3));
		this.txt_tip.text="加载完成，开始解析配置"+per.toFixed(2)+"%…";
		this.pro_loading.value=0.9+(per*0.001);
		this.progressMoni.value=per *0.01;
		if(AdaptConfig.ZlibEnabled){
			Watcher.ins.tick("parserCfg:uncompress"+url);
			var b=new ByteArray(d);
			try{
				b.uncompress();
				var json=b.readUTFBytes(b.length);
				CfgManager.parserDataToConfig(JSON.parse(json));
				b.clear();
			}
			catch(error){
				Laya.timer.clear(this,this.init);
				Laya.timer.clear(this,this.parserCfg);
				b.clear();
				this.txt_tip.text="解析失败，开始重新加载！";
				AdaptConfig.ZlibEnabled=false;
				this.loadCount=0;
				this.clientAry=null;
				this.urlClient(true,Handler.create(this,this.onUIProgress,null,false));
				return;
			}
			Watcher.ins.stop("parserCfg:uncompress"+url);
		}
		else{
			if((d instanceof ArrayBuffer))return;
			CfgManager.parserDataToConfig(d);
		}
		Laya.loader.clearRes(url);
	}
