	__proto.refreshPriList=function(){
		this.btn_send.disabled=true;
		this.infoList.y=0;
		this.infoList.removeChildren(0,this.infoList._childs.length);
		this.infoList.height=0;
		var temparr=[];
		var index=0;
		var lastRender;
		var count=0;
		for(var name in this.chatMgr.priObj){
			var render=this.chatMgr.priRenderCacheArr.length>0?this.chatMgr.priRenderCacheArr.pop():new ChatPriRenderView();
			render.dataSource=[this.chatMgr.priObj[name],name];
			CornerUtil.removeCorner(render);
			temparr.push(render);
			this.infoList.addChild(render);
			if(lastRender){
				render.y=lastRender.y+lastRender.height;
			}
			lastRender=render;
			render.y=count++;
			if(this.chatMgr.priJiLuObj.get(name)){
				CornerUtil.addCorner(render,464,0);
				render.updateTime();
			}
		}
		this.chatMgr.priRenderCacheArr=temparr;
	}
	
